create extension if not exists pgcrypto;

create type public.app_role as enum ('agency_admin','agency_staff','property_owner','property_manager','property_staff');
create type public.property_status as enum ('active','paused','onboarding');
create type public.enquiry_status as enum ('new','open','waiting','won','lost','closed');
create type public.message_role as enum ('guest','human','ai','system');
create type public.task_status as enum ('todo','in_progress','blocked','done','cancelled');
create type public.task_priority as enum ('low','normal','high','urgent');
create type public.review_status as enum ('new','draft','approved','published','ignored');
create type public.integration_status as enum ('disconnected','pending','connected','error');

create table public.organizations(id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, created_at timestamptz not null default now());
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organization_members(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.app_role not null, created_at timestamptz not null default now(), unique(organization_id,user_id));
create table public.properties(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, island text not null, atoll text, country text not null default 'Maldives', status public.property_status not null default 'onboarding', timezone text not null default 'Indian/Maldives', currency text not null default 'MVR', phone text, email text, address text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.property_users(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role public.app_role not null, created_at timestamptz not null default now(), unique(property_id,user_id));
create table public.rooms(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, name text not null, room_type text, capacity int not null default 2, status text not null default 'active', created_at timestamptz not null default now());
create table public.guests(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, first_name text not null, last_name text, email text, phone text, nationality text, passport_number text, national_id text, date_of_birth date, gender text, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reservations(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, guest_id uuid references public.guests(id) on delete set null, room_id uuid references public.rooms(id) on delete set null, source text, external_id text, check_in date, check_out date, adults int not null default 1, children int not null default 0, status text not null default 'confirmed', total_amount numeric(12,2), currency text not null default 'MVR', special_requests text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.enquiries(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, guest_id uuid references public.guests(id) on delete set null, reservation_id uuid references public.reservations(id) on delete set null, channel text not null, status public.enquiry_status not null default 'new', subject text, assigned_to uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.conversations(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, guest_id uuid references public.guests(id) on delete set null, enquiry_id uuid references public.enquiries(id) on delete set null, channel text not null, external_thread_id text, human_takeover boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.conversation_messages(id uuid primary key default gen_random_uuid(), conversation_id uuid not null references public.conversations(id) on delete cascade, role public.message_role not null, body text not null, confidence numeric(5,4), requires_approval boolean not null default false, approved_by uuid references auth.users(id) on delete set null, approved_at timestamptz, external_message_id text, created_at timestamptz not null default now());
create table public.knowledge_categories(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, name text not null, created_at timestamptz not null default now());
create table public.knowledge_items(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, category_id uuid references public.knowledge_categories(id) on delete set null, title text not null, content text not null, verified boolean not null default false, active boolean not null default true, source text, verified_by uuid references auth.users(id) on delete set null, verified_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tasks(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, assigned_to uuid references auth.users(id) on delete set null, title text not null, description text, status public.task_status not null default 'todo', priority public.task_priority not null default 'normal', due_at timestamptz, source text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reviews(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, source text not null, external_id text, rating numeric(3,2), review_text text, status public.review_status not null default 'new', ai_draft text, published_response text, reviewed_at timestamptz, created_at timestamptz not null default now());
create table public.digital_audits(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, property_id uuid references public.properties(id) on delete set null, target_name text not null, target_url text, score int, summary text, created_at timestamptz not null default now());
create table public.audit_items(id uuid primary key default gen_random_uuid(), audit_id uuid not null references public.digital_audits(id) on delete cascade, category text not null, title text not null, severity text not null default 'info', finding text, recommendation text, created_at timestamptz not null default now());
create table public.automations(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, name text not null, trigger_type text not null, enabled boolean not null default true, config jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.automation_runs(id uuid primary key default gen_random_uuid(), automation_id uuid not null references public.automations(id) on delete cascade, status text not null, input jsonb, output jsonb, error text, started_at timestamptz not null default now(), finished_at timestamptz);
create table public.integrations(id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, property_id uuid references public.properties(id) on delete cascade, provider text not null, status public.integration_status not null default 'disconnected', metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.guest_journey_events(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, guest_id uuid references public.guests(id) on delete set null, reservation_id uuid references public.reservations(id) on delete set null, event_type text not null, scheduled_for timestamptz, completed_at timestamptz, status text not null default 'pending', metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tax_profiles(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, gst_registered boolean not null default false, gst_rate numeric(6,3), green_tax_rate numeric(12,2), tax_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.tax_transactions(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, reservation_id uuid references public.reservations(id) on delete set null, transaction_type text not null, taxable_amount numeric(12,2) not null default 0, gst_amount numeric(12,2) not null default 0, green_tax_amount numeric(12,2) not null default 0, currency text not null default 'MVR', occurred_at timestamptz not null default now());
create table public.mgis_records(id uuid primary key default gen_random_uuid(), property_id uuid not null references public.properties(id) on delete cascade, guest_id uuid references public.guests(id) on delete set null, reservation_id uuid references public.reservations(id) on delete set null, submission_status text not null default 'DRAFT', validation_status text, validation_errors jsonb, external_reference text, last_submitted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, property_id uuid references public.properties(id) on delete cascade, title text not null, body text, read_at timestamptz, created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(), organization_id uuid references public.organizations(id) on delete set null, property_id uuid references public.properties(id) on delete set null, actor_user_id uuid references auth.users(id) on delete set null, action text not null, entity_type text, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
